package org.dextur.reputation.domain.policy;

import java.time.Instant;
import java.util.*;
import org.dextur.reputation.api.ReputationSnapshot;
import org.dextur.reputation.domain.protection.Fixed;

/** Dedicated administration ledger. Profile.systemScore remains the compatible aggregate of non-community contributions. */
public final class AdministrationData {
    private AdministrationData(){}
    public enum Type { SET,ADD,REMOVE,LOCK,UNLOCK,OVERRIDE }
    public enum Override { FORCE_ALLOW,FORCE_DENY,DEFAULT }
    public record Request(UUID operation,UUID player,String scope,Type type,long requested,String policy,Override override,String actor,String reason,Instant at){public Request{Objects.requireNonNull(operation);Objects.requireNonNull(player);Objects.requireNonNull(type);Objects.requireNonNull(override);Objects.requireNonNull(at);Objects.requireNonNull(policy);Objects.requireNonNull(reason);if(!scope.matches("[a-z0-9_-]{1,32}")||reason.length()>1000||!actor.equals("CONSOLE")&&!actor.equals(UUID.fromString(actor).toString()))throw new IllegalArgumentException("Administration request");if(!Set.of(Type.SET,Type.ADD,Type.REMOVE).contains(type)&&requested!=0)throw new IllegalArgumentException("Unexpected administrative amount");if(type==Type.OVERRIDE)PolicyRules.identifier(policy);else if(!policy.isEmpty()||override!=Override.DEFAULT)throw new IllegalArgumentException("Unexpected override");}public String payload(){return player+"/"+scope+"/"+type+"/"+requested+"/"+policy+"/"+override+"/"+actor+"/"+reason;}}
    public record Audit(int model,Request request,long previousVisible,long resultingVisible,long previousAdmin,long resultingAdmin,long community,long nonAdminSystem,boolean previousLock,boolean resultingLock,Map<String,Override> previousOverrides,Map<String,Override> resultingOverrides,long minimum,long maximum,long maximumSingle){public Audit{previousOverrides=Map.copyOf(previousOverrides);resultingOverrides=Map.copyOf(resultingOverrides);if(model!=1||Math.addExact(Math.addExact(community,nonAdminSystem),previousAdmin)!=previousVisible||Math.addExact(Math.addExact(community,nonAdminSystem),resultingAdmin)!=resultingVisible)throw new IllegalArgumentException("Administration audit projection");long delta=Math.subtractExact(resultingAdmin,previousAdmin);if(Set.of(Type.SET,Type.ADD,Type.REMOVE).contains(request.type())){if(resultingVisible<minimum||resultingVisible>maximum||delta>maximumSingle||delta< -maximumSingle)throw new IllegalArgumentException("Administration audit bounds");long expected=switch(request.type()){case SET->Math.subtractExact(request.requested(),previousVisible);case ADD->request.requested();case REMOVE->Math.negateExact(request.requested());default->0;};if(delta!=expected||request.type()==Type.REMOVE&&request.requested()<=0)throw new IllegalArgumentException("Administration audit amount");}else if(delta!=0)throw new IllegalArgumentException("Non-adjustment delta");Fixed.units(resultingAdmin);if(request.type()!=Type.LOCK&&request.type()!=Type.UNLOCK&&previousLock!=resultingLock||request.type()==Type.LOCK&&!resultingLock||request.type()==Type.UNLOCK&&resultingLock)throw new IllegalArgumentException("Lock audit");var expectedOverrides=new TreeMap<>(previousOverrides);if(request.type()==Type.OVERRIDE){if(request.override()==Override.DEFAULT)expectedOverrides.remove(request.policy());else expectedOverrides.put(request.policy(),request.override());}if(!expectedOverrides.equals(resultingOverrides))throw new IllegalArgumentException("Override audit");}}
    public record State(UUID player,String scope,long revision,long contribution,boolean votingLocked,Map<String,Override> overrides,List<Audit> audit){public State{overrides=Collections.unmodifiableMap(new TreeMap<>(overrides));audit=List.copyOf(audit);if(revision!=audit.size()||audit.size()>10000||overrides.size()>256)throw new IllegalArgumentException("Administration history bounds");long total=0;boolean locked=false;Map<String,Override> previous=Map.of();var operations=new HashSet<UUID>();Instant at=Instant.EPOCH;for(var row:audit){if(!row.request().player().equals(player)||!row.request().scope().equals(scope)||!operations.add(row.request().operation())||row.previousAdmin()!=total||row.previousLock()!=locked||!row.previousOverrides().equals(previous)||row.request().at().isBefore(at))throw new IllegalArgumentException("Administration audit chain");total=row.resultingAdmin();locked=row.resultingLock();previous=row.resultingOverrides();at=row.request().at();}if(total!=contribution||locked!=votingLocked||!previous.equals(overrides))throw new IllegalArgumentException("Administration aggregate");}public String key(){return player+"/"+scope;}public static State empty(UUID p,String s){return new State(p,s,0,0,false,Map.of(),List.of());}}
    public record Change(State state,ReputationSnapshot profile,Audit audit,boolean duplicate){}
    public static Change apply(State old,ReputationSnapshot profile,Request r,PolicyRules.Limits limits){State before=old==null?State.empty(r.player(),r.scope()):old;for(var event:before.audit())if(event.request().operation().equals(r.operation())){if(!event.request().payload().equals(r.payload()))throw new IllegalArgumentException("ADMIN_ID_CONFLICT");return new Change(before,profile,event,true);}if(limits.requireReason()&&r.reason().isBlank())throw new IllegalArgumentException("ADMIN_REASON");Instant effective=r.at().isBefore(profile.updatedAt())?profile.updatedAt():r.at();if(!before.audit().isEmpty()&&effective.isBefore(before.audit().getLast().request().at()))effective=before.audit().getLast().request().at();if(!effective.equals(r.at()))r=new Request(r.operation(),r.player(),r.scope(),r.type(),r.requested(),r.policy(),r.override(),r.actor(),r.reason(),effective);if(r.type()==Type.OVERRIDE&&r.policy().equals("support.emergency-contact"))throw new IllegalArgumentException("ADMIN_EMERGENCY");long delta=switch(r.type()){case SET->Math.subtractExact(r.requested(),profile.visibleScore());case ADD->r.requested();case REMOVE->{if(r.requested()<=0)throw new IllegalArgumentException("ADMIN_REMOVE");yield Math.negateExact(r.requested());}default->0;};long total=Math.addExact(before.contribution(),delta),system=Math.addExact(profile.systemScore(),delta),visible=Math.addExact(profile.visibleScore(),delta);Fixed.units(total);if(Set.of(Type.SET,Type.ADD,Type.REMOVE).contains(r.type()))Fixed.units(system);var overrides=new TreeMap<>(before.overrides());if(r.type()==Type.OVERRIDE){if(r.override()==Override.DEFAULT)overrides.remove(r.policy());else overrides.put(r.policy(),r.override());}boolean lock=r.type()==Type.LOCK||r.type()!=Type.UNLOCK&&before.votingLocked();var event=new Audit(1,r,profile.visibleScore(),visible,before.contribution(),total,profile.communityScore(),Math.subtractExact(profile.systemScore(),before.contribution()),before.votingLocked(),lock,before.overrides(),overrides,limits.minimum(),limits.maximum(),limits.single());var history=new ArrayList<>(before.audit());history.add(event);var next=new State(r.player(),r.scope(),before.revision()+1,total,lock,overrides,history);var p=new ReputationSnapshot(profile.playerId(),profile.scopeId(),profile.communityScore(),system,visible,profile.tier(),Math.incrementExact(profile.revision()),profile.createdAt(),r.at());return new Change(next,p,event,false);}
}
